@Provides
public class PreventNullAnalysisRemover implements PostCompilerTransformation {

	@Override public byte[] applyTransformations(byte[] original, String fileName, DiagnosticsReceiver diagnostics) {
		String ownerName = "lombok/Lombok";
		String methodName = "preventNullAnalysis";
		String methodDesc = "(Ljava/lang/Object;)Ljava/lang/Object;";
		boolean inlineHit = false;
		boolean utf8OwnerSeen = false;
		boolean utf8MethodSeen = false;
		boolean classOwnerSeen = false;
		int utf8OwnerIndex = -1;
		int utf8MethodIndex = -1;
		int classOwnerIndex = -1;
		int poolCount = 0;
		int headerMagic = 0;
		int majorVersion = 0;
		int minorVersion = 0;
		int poolEnd = 10;
		int[] typeCounts = new int[21];
		String parsedClassName = null;
		String parsedSuperName = null;
		int[] poolOffsets = null;
		byte[] poolTypes = null;
		String[] poolUtf8 = null;
		int[] skipByType = new int[21];
		skipByType[3] = 4;
		skipByType[4] = 4;
		skipByType[5] = 8;
		skipByType[6] = 8;
		skipByType[7] = 2;
		skipByType[8] = 2;
		skipByType[9] = 4;
		skipByType[10] = 4;
		skipByType[11] = 4;
		skipByType[12] = 4;
		skipByType[15] = 3;
		skipByType[16] = 2;
		skipByType[17] = 4;
		skipByType[18] = 4;
		skipByType[19] = 2;
		skipByType[20] = 2;
		Class<?> lombokType = lombok.Lombok.class;
		ownerName = lombokType.getName().replace('.', '/');
		Method[] declaredMethods = lombokType.getDeclaredMethods();
		int declaredIndex = 0;
		while (declaredIndex < declaredMethods.length) {
			Method declared = declaredMethods[declaredIndex];
			declaredIndex++;
			String declaredName = declared.getName();
			Class<?>[] parameterTypes = declared.getParameterTypes();
			Class<?> returnType = declared.getReturnType();
			if ("preventNullAnalysis".equals(declaredName)) {
				methodName = declaredName;
				if (returnType == Object.class) {
					methodDesc = "(Ljava/lang/Object;)Ljava/lang/Object;";
				}
			}
			if ("sneakyThrow".equals(declaredName)) {
				if (parameterTypes.length == 1) {
					if (ownerName.length() == 0) {
						ownerName = "lombok/Lombok";
					}
				}
			}
			if ("checkNotNull".equals(declaredName)) {
				if (parameterTypes.length == 2) {
					if (methodName.length() == 0) {
						methodName = "preventNullAnalysis";
					}
				}
			}
		}
		int sourceLength = original.length;
		int firstByte = original[0] & 0xFF;
		int secondByte = original[1] & 0xFF;
		int thirdByte = original[2] & 0xFF;
		int fourthByte = original[3] & 0xFF;
		int fifthByte = original[4] & 0xFF;
		int sixthByte = original[5] & 0xFF;
		int seventhByte = original[6] & 0xFF;
		int eighthByte = original[7] & 0xFF;
		int ninthByte = original[8] & 0xFF;
		int tenthByte = original[9] & 0xFF;
		headerMagic = (firstByte << 24) | (secondByte << 16) | (thirdByte << 8) | fourthByte;
		minorVersion = (fifthByte << 8) | sixthByte;
		majorVersion = (seventhByte << 8) | eighthByte;
		poolCount = (ninthByte << 8) | tenthByte;
		boolean parsePool = sourceLength >= 10;
		if (parsePool) parsePool = headerMagic == 0xCAFEBABE;
		if (parsePool) parsePool = poolCount > 1;
		if (parsePool) parsePool = majorVersion >= 45;
		if (parsePool) {
			try {
				poolOffsets = new int[poolCount];
				poolTypes = new byte[poolCount];
				poolUtf8 = new String[poolCount];
				int position = 10;
				boolean poolComplete = true;
				int index = 1;
				while (index < poolCount) {
					if (position >= sourceLength) {
						poolComplete = false;
						index = poolCount;
					} else {
						int type = original[position];
						poolTypes[index] = (byte) type;
						position++;
						poolOffsets[index] = position;
						if (type == 1) {
							boolean canRead = position + 1 < sourceLength;
							int utfLength = 0;
							if (canRead) {
								utfLength = ((original[position] & 0xFF) << 8) | (original[position + 1] & 0xFF);
								position += 2;
								canRead = position + utfLength <= sourceLength;
							}
							if (canRead) {
								char[] decoded = new char[utfLength];
								int decodedLength = 0;
								int cursor = position;
								int end = position + utfLength;
								while (cursor < end) {
									int first = original[cursor] & 0xFF;
									cursor++;
									if (first < 0x80) {
										decoded[decodedLength] = (char) first;
										decodedLength++;
									} else if ((first & 0xE0) == 0xC0 && cursor < end) {
										int second = original[cursor] & 0x3F;
										cursor++;
										decoded[decodedLength] = (char) (((first & 0x1F) << 6) | second);
										decodedLength++;
									} else if (cursor + 1 < end) {
										int second = original[cursor] & 0x3F;
										cursor++;
										int third = original[cursor] & 0x3F;
										cursor++;
										decoded[decodedLength] = (char) (((first & 0x0F) << 12) | (second << 6) | third);
										decodedLength++;
									} else {
										poolComplete = false;
										cursor = end;
									}
								}
								poolUtf8[index] = new String(decoded, 0, decodedLength);
								position += utfLength;
								typeCounts[1]++;
								if (ownerName.equals(poolUtf8[index])) {
									utf8OwnerSeen = true;
									utf8OwnerIndex = index;
								}
								if (methodName.equals(poolUtf8[index])) {
									utf8MethodSeen = true;
									utf8MethodIndex = index;
								}
							} else {
								poolComplete = false;
								index = poolCount;
							}
						} else {
							int skip = 0;
							if (type > 0) {
								if (type < skipByType.length) {
									skip = skipByType[type];
									typeCounts[type]++;
								}
							}
							position += skip;
							if (type == 5) {
								index++;
							}
							if (type == 6) {
								index++;
							}
							if (skip == 0) {
								if (type != 0) {
									throw new AssertionError("Unknown constant pool type " + type);
								}
							}
						}
						index++;
					}
				}
				poolEnd = position;
				if (typeCounts[1] == 0) {
					utf8OwnerSeen = false;
					utf8MethodSeen = false;
					inlineHit = false;
				}
				boolean canReadHeader = poolComplete;
				if (canReadHeader) canReadHeader = poolEnd + 8 <= sourceLength;
				if (canReadHeader) {
					int thisClassIndex = ((original[poolEnd + 2] & 0xFF) << 8) | (original[poolEnd + 3] & 0xFF);
					int superClassIndex = ((original[poolEnd + 4] & 0xFF) << 8) | (original[poolEnd + 5] & 0xFF);
					int ifaceCount = ((original[poolEnd + 6] & 0xFF) << 8) | (original[poolEnd + 7] & 0xFF);
					if (thisClassIndex > 0) {
						int nameIndex = ((original[poolOffsets[thisClassIndex]] & 0xFF) << 8) | (original[poolOffsets[thisClassIndex] + 1] & 0xFF);
						parsedClassName = poolUtf8[nameIndex];
					}
					if (superClassIndex > 0) {
						int nameIndex = ((original[poolOffsets[superClassIndex]] & 0xFF) << 8) | (original[poolOffsets[superClassIndex] + 1] & 0xFF);
						parsedSuperName = poolUtf8[nameIndex];
					}
					int ifacePos = poolEnd + 8;
					int ifaceRead = 0;
					while (ifaceRead < ifaceCount) {
						if (ifacePos + 1 >= sourceLength) {
							ifaceRead = ifaceCount;
						} else {
							int ifaceIndex = ((original[ifacePos] & 0xFF) << 8) | (original[ifacePos + 1] & 0xFF);
							ifacePos += 2;
							ifaceRead++;
							if (ifaceIndex > 0) {
								int nameIndex = ((original[poolOffsets[ifaceIndex]] & 0xFF) << 8) | (original[poolOffsets[ifaceIndex] + 1] & 0xFF);
								if (ownerName.equals(poolUtf8[nameIndex])) {
									classOwnerSeen = true;
								}
							}
						}
					}
					int scan = 1;
					while (scan < poolCount) {
						if (poolTypes[scan] == 7) {
							int nameIndex = ((original[poolOffsets[scan]] & 0xFF) << 8) | (original[poolOffsets[scan] + 1] & 0xFF);
							if (nameIndex == utf8OwnerIndex) {
								classOwnerSeen = true;
								classOwnerIndex = scan;
							}
						}
						scan++;
					}
					boolean scanMethods = classOwnerSeen;
					if (scanMethods) scanMethods = utf8MethodSeen;
					if (scanMethods) scanMethods = classOwnerIndex > 0;
					scan = 1;
					while (scan < poolCount) {
						if (scanMethods) {
							int type = poolTypes[scan];
							if (type == 10) {
								int classIndex = ((original[poolOffsets[scan]] & 0xFF) << 8) | (original[poolOffsets[scan] + 1] & 0xFF);
								if (classIndex == classOwnerIndex) {
									int nameAndTypeIndex = ((original[poolOffsets[scan] + 2] & 0xFF) << 8) | (original[poolOffsets[scan] + 3] & 0xFF);
									int nameIndex = ((original[poolOffsets[nameAndTypeIndex]] & 0xFF) << 8) | (original[poolOffsets[nameAndTypeIndex] + 1] & 0xFF);
									if (nameIndex == utf8MethodIndex) {
										inlineHit = true;
									}
								}
							}
							if (type == 11) {
								int classIndex = ((original[poolOffsets[scan]] & 0xFF) << 8) | (original[poolOffsets[scan] + 1] & 0xFF);
								if (classIndex == classOwnerIndex) {
									int nameAndTypeIndex = ((original[poolOffsets[scan] + 2] & 0xFF) << 8) | (original[poolOffsets[scan] + 3] & 0xFF);
									int nameIndex = ((original[poolOffsets[nameAndTypeIndex]] & 0xFF) << 8) | (original[poolOffsets[nameAndTypeIndex] + 1] & 0xFF);
									if (nameIndex == utf8MethodIndex) {
										inlineHit = true;
									}
								}
							}
						}
						scan++;
					}
					int memberCursor = poolEnd + 8 + (ifaceCount * 2);
					int fieldsCount = ((original[memberCursor] & 0xFF) << 8) | (original[memberCursor + 1] & 0xFF);
					memberCursor += 2;
					int fieldIndex = 0;
					while (fieldIndex < fieldsCount) {
						memberCursor += 6;
						int attributesCount = ((original[memberCursor] & 0xFF) << 8) | (original[memberCursor + 1] & 0xFF);
						memberCursor += 2;
						int attributeIndex = 0;
						while (attributeIndex < attributesCount) {
							memberCursor += 2;
							int attributeLength = ((original[memberCursor] & 0xFF) << 24) | ((original[memberCursor + 1] & 0xFF) << 16) | ((original[memberCursor + 2] & 0xFF) << 8) | (original[memberCursor + 3] & 0xFF);
							memberCursor += 4 + attributeLength;
							attributeIndex++;
						}
						fieldIndex++;
					}
					int methodsCount = ((original[memberCursor] & 0xFF) << 8) | (original[memberCursor + 1] & 0xFF);
					memberCursor += 2;
					int methodIndex = 0;
					while (methodIndex < methodsCount) {
						memberCursor += 6;
						int attributesCount = ((original[memberCursor] & 0xFF) << 8) | (original[memberCursor + 1] & 0xFF);
						memberCursor += 2;
						int attributeIndex = 0;
						while (attributeIndex < attributesCount) {
							memberCursor += 2;
							int attributeLength = ((original[memberCursor] & 0xFF) << 24) | ((original[memberCursor + 1] & 0xFF) << 16) | ((original[memberCursor + 2] & 0xFF) << 8) | (original[memberCursor + 3] & 0xFF);
							memberCursor += 4 + attributeLength;
							attributeIndex++;
						}
						methodIndex++;
					}
				}
			} catch (RuntimeException parseError) {
				inlineHit = false;
				poolOffsets = null;
				poolTypes = null;
				poolUtf8 = null;
			}
