import java.io.File;
import lombok.bytecode.ClassFileMetaData;
import lombok.core.DiagnosticsReceiver;
import lombok.core.PostCompiler;
import lombok.bytecode.TestClassFileMetaData;

public class CheckLombokTraces {
	public static void main(String[] args) throws Exception {
		check("PostCompileSneaky.java", "sneakyThrow");
		check("PostCompilePreventNullAnalysis.java", "preventNullAnalysis");
	}

	static void check(String file, String method) throws Exception {
		byte[] compiled = TestClassFileMetaData.compile(new File("test/bytecode/resource/" + file));
		DiagnosticsReceiver receiver = new DiagnosticsReceiver() {
			public void addWarning(String message) { System.out.println("WARN: " + message); }
			public void addError(String message) { System.out.println("ERROR: " + message); }
		};
		byte[] transformed = PostCompiler.applyTransformations(compiled, file, receiver);
		String pool = new ClassFileMetaData(transformed).poolContent();
		System.out.println(file + " before=" + compiled.length + " after=" + transformed.length);
		System.out.println("contains lombok/Lombok: " + pool.contains("lombok/Lombok"));
		System.out.println("contains " + method + ": " + pool.contains(method));
		if (pool.contains("lombok/Lombok") || pool.contains(method)) {
			System.out.println(pool);
			throw new AssertionError("Still traces of lombok in " + file);
		}
	}
}

